/**
 * Clean up a beatmap generated by Mapperatorinator and check it against the request.
 * Pure (no Node APIs), so the CLI, the editor server and the browser can all use it.
 */
import { type Beatmap, parseOsu, getKeys, setKeys } from '../core/beatmap';
import { fixOverlaps, validate, breakFastJacks } from '../tools/transforms';
import { classifyPatterns } from '../analysis/patterns';

export interface AiPostOptions {
  keys: number;
  stars?: number;
  audioFilename?: string;
  title?: string;
  artist?: string;
  requestedTags?: string[];
  /** which AI made it (tags and credits follow its disclosure rules) */
  engine?: 'mapperatorinator' | 'mug';
}

export interface StyleCheck {
  tag: string;
  /** the classifier's rule score for the tag (0..1), if it has a rule */
  score?: number;
  /** true when the generated map shows the requested style */
  matched: boolean;
}

export interface AiPostResult {
  map: Beatmap;
  removedOverlaps: number;
  errors: number;
  styleCheck: StyleCheck[];
}

export function postprocessAiMap(osuText: string, o: AiPostOptions): AiPostResult {
  let map = parseOsu(osuText);
  if (getKeys(map) !== o.keys) setKeys(map, o.keys);
  const before = map.notes.length;
  // a long note snapped to zero (or negative) length is a plain note
  for (const n of map.notes) if (n.endTime !== undefined && n.endTime <= n.time) delete n.endTime;
  map = fixOverlaps(map);
  // 7K: fast jacks inside streams (rows of 1-2 notes) move to a free column; jacked chords stay.
  // On 24 held-out hard 7K AI sections: 14.4 -> 11.0 fast jacks per 1000 notes (ranked 2.8), same
  // pattern mix. In 4K and 6K the AI has fewer fast jacks than ranked maps, so they are left alone.
  if (o.keys === 7 && o.engine !== 'mug') map = breakFastJacks(map, { maxRowSize: 2 }).map;
  const md = map.metadata;
  if (o.title) { md.set('Title', o.title); md.set('TitleUnicode', o.title); }
  if (o.artist) { md.set('Artist', o.artist); md.set('ArtistUnicode', o.artist); }
  md.set('Version', `${o.keys}K AI${o.stars !== undefined ? ` ${o.stars}*` : ''}`);
  if (!md.get('Creator') || md.get('Creator') === 'Mapperatorinator') md.set('Creator', 'maniamap');
  // both AIs ask users to always disclose AI use (MuG Diffusion also keeps its AIMode line)
  const tags = new Set((md.get('Tags') ?? '').split(/\s+/).filter(Boolean));
  (o.engine === 'mug' ? ['ai-generated', 'mug-diffusion', 'maniamap'] : ['ai-generated', 'mapperatorinator', 'maniamap']).forEach((t) => tags.add(t));
  md.set('Tags', [...tags].join(' '));
  if (o.audioFilename) map.general.set('AudioFilename', o.audioFilename);
  map.general.set('Mode', '3');

  const r = classifyPatterns(map);
  const suggested = new Map(r.suggestedTags.map((t) => [t.tag, t.score]));
  const styleCheck = (o.requestedTags ?? []).map((tag) => {
    const score = r.tagScores[tag];
    return { tag, score, matched: suggested.has(tag) || (score !== undefined && score >= 0.5) };
  });
  return {
    map,
    removedOverlaps: before - map.notes.length,
    errors: validate(map).filter((i) => i.severity === 'error').length,
    styleCheck,
  };
}
